<script lang="ts">
  import type { OperationsPayload } from '../lib/types';

  export let operations: OperationsPayload;

  $: coverage = operations.live_coverage;
  $: pollProgress = Math.min(100, (coverage.polls / coverage.min_polls) * 100);
</script>

<aside class:ready={coverage.gate_satisfied} class="data-gate" aria-labelledby="data-gate-title">
  <div class="data-gate-copy">
    <span class="status-dot" aria-hidden="true"></span>
    <div>
      <p class="mini-label">Estado dos dados</p>
      <h2 id="data-gate-title">{coverage.gate_satisfied ? 'Cobertura mínima atingida' : `Aguardando mais ${Math.max(0, coverage.min_polls - coverage.polls)} pesquisa${coverage.min_polls - coverage.polls === 1 ? '' : 's'}`}</h2>
      <p>{coverage.gate_satisfied ? 'O gate estatístico foi satisfeito.' : 'Os números publicados estão visíveis; consenso e chances continuam bloqueados.'}</p>
    </div>
  </div>
  <div class="gate-progress" role="group" aria-label={`${coverage.polls} de ${coverage.min_polls} pesquisas necessárias`}>
    <div class="gate-progress-heading"><span>Pesquisas na janela</span><strong>{coverage.polls}/{coverage.min_polls}</strong></div>
    <div class="gate-track" role="progressbar" aria-label="Pesquisas validadas na janela" aria-valuemin="0" aria-valuemax={coverage.min_polls} aria-valuenow={coverage.polls}>
      <span style={`width:${pollProgress}%`}></span>
    </div>
  </div>
  <dl class="gate-checks">
    <div><dt>Casas independentes</dt><dd class:met={coverage.houses >= coverage.min_houses}>{coverage.houses}/{coverage.min_houses}<span class="sr-only"> {coverage.houses >= coverage.min_houses ? 'requisito atendido' : 'requisito pendente'}</span></dd></div>
    <div><dt>Janela móvel</dt><dd>{coverage.window_days} dias</dd></div>
  </dl>
</aside>
