<script lang="ts">
  /**
   * Histórico de erro por casa.
   *
   * Two layers, deliberately separated: a plain-language layer on top (one
   * sentence per house × election × candidate, with an arrow for direction)
   * and the full statistics underneath, inside a disclosure so the reader who
   * wants the rigour can open it and the reader who does not is not buried in
   * tables.
   */
  import { onMount } from 'svelte';
  import DataTable from '../components/DataTable.svelte';
  import HouseErrorChart from '../components/HouseErrorChart.svelte';
  import HouseErrorPlain from '../components/HouseErrorPlain.svelte';
  import HouseHeatmap from '../components/HouseHeatmap.svelte';
  import { formatNumber, formatSigned } from '../lib/format';
  import type { HistoryBundle } from '../lib/types';

  export let history: HistoryBundle;

  type MetricId = 'mae' | 'margin';
  type ViewId = 'dots' | 'bars' | 'heatmap';

  const WINDOWS = [
    { id: 'last_by_house', label: 'Última de cada casa' },
    { id: 'd7', label: 'D-7' },
    { id: 'd14', label: 'D-14' },
    { id: 'd30', label: 'D-30' },
    { id: 'campaign', label: 'Campanha inteira' },
  ];

  let windowId = 'last_by_house';
  let metric: MetricId = 'mae';
  let view: ViewId = 'dots';
  let selectedHouse = '';
  let rigorOpen = false;
  let ready = false;

  onMount(() => {
    const sync = () => {
      const params = new URLSearchParams(window.location.search);
      const janela = params.get('janela');
      const metrica = params.get('metrica');
      const vista = params.get('vista');
      if (janela && WINDOWS.some((option) => option.id === janela)) windowId = janela;
      if (metrica === 'mae' || metrica === 'margin') metric = metrica;
      if (vista === 'dots' || vista === 'bars' || vista === 'heatmap') view = vista;
      selectedHouse = params.get('casa') ?? '';
      // A deep link into the statistics opens them; a plain visit does not.
      if (janela || metrica || vista || params.get('rigor') === '1') rigorOpen = true;
      ready = true;
    };
    sync();
    window.addEventListener('popstate', sync);
    return () => window.removeEventListener('popstate', sync);
  });

  function persist(mode: 'push' | 'replace' = 'replace'): void {
    if (!ready) return;
    const url = new URL(window.location.href);
    url.searchParams.set('janela', windowId);
    url.searchParams.set('metrica', metric);
    url.searchParams.set('vista', view);
    if (selectedHouse) url.searchParams.set('casa', selectedHouse);
    else url.searchParams.delete('casa');
    const next = `${url.pathname}${url.search}${url.hash}`;
    if (next === `${window.location.pathname}${window.location.search}${window.location.hash}`) return;
    if (mode === 'push') window.history.pushState({}, '', next);
    else window.history.replaceState({}, '', next);
  }

  function selectHouse(id: string): void {
    selectedHouse = id;
    persist('push');
  }

  $: summary = history.lab.summaries[windowId] ?? history.lab.summaries.last_by_house;
  $: grandMean = (summary?.pooling?.mae?.grand_mean as number | null) ?? null;
  $: pooledK = (summary?.pooling?.mae?.k as number | null) ?? null;
  $: houses = (summary?.houses ?? []).slice().sort((a, b) => (a.mae_raw ?? 99) - (b.mae_raw ?? 99));
  $: cells = summary?.cells ?? [];
  $: effects = Object.values(summary?.election_effects ?? {}).sort(
    (a, b) => a.year - b.year || a.turn - b.turn,
  );
  $: detail = houses.find((house) => house.house_id === selectedHouse) ?? null;
  $: detailCells = cells
    .filter((cell) => cell.house_id === selectedHouse)
    .sort((a, b) => a.year - b.year || a.turn - b.turn);
  $: coverage = history.lab.coverage;
  $: persistence = history.lab.persistence.relative_margin_error;
  $: definitions = history.lab.metric_definitions;
  $: ideology = history.correction.ideology;
  $: plainRows = ideology.plain_errors;
  $: worstCommon = effects.length ? [...effects].sort((a, b) => Math.abs(b.common_margin_error) - Math.abs(a.common_margin_error))[0] : null;
</script>

<section class="page-stack" aria-labelledby="errorlab-title">
  <header class="page-hero compact-hero">
    <p class="eyebrow">Histórico de erro</p>
    <h1 id="errorlab-title">Quanto cada casa errou nas eleições passadas</h1>
    <p>
      {coverage.totals.scored_observations} pesquisas de {coverage.totals.houses} casas, comparadas
      com o resultado da urna em 2010, 2014, 2018 e 2022. Primeiro e segundo turno são lidos
      separadamente, nunca somados.
    </p>
  </header>

  <section class="lab-summary" aria-label="Resumo em três frases">
    <article>
      <span>Erro típico por candidatura</span>
      <strong>{grandMean === null ? '—' : `${formatNumber(grandMean)} p.p.`}</strong>
      <small>média entre casas, {WINDOWS.find((w) => w.id === windowId)?.label?.toLowerCase()} (o nome técnico é MAE)</small>
    </article>
    <article>
      <span>Quando todo mundo errou junto</span>
      <strong>{worstCommon ? `${formatSigned(worstCommon.common_margin_error)} p.p.` : '—'}</strong>
      <small>{worstCommon ? `${worstCommon.turn === 1 ? '1º' : '2º'} turno de ${worstCommon.year}: erro comum a todas as casas na diferença entre 1º e 2º colocados` : ''}</small>
    </article>
    <article>
      <span>Dá para corrigir pelo passado?</span>
      <strong>{persistence.correction_authorized ? 'Sim' : 'Não'}</strong>
      <small>correção de viés por casa {persistence.correction_authorized ? 'autorizada' : 'não autorizada'}: o erro passado de uma casa não prevê o próximo — nem por candidato, nem por lado do espectro</small>
    </article>
    <article>
      <span>O que falta no corpus</span>
      <strong>{coverage.totals.cells_absent}</strong>
      <small>eleições/turnos sem pesquisas preservadas, listados como lacunas explícitas</small>
    </article>
  </section>

  <HouseErrorPlain
    rows={plainRows}
    summaries={ideology.house_summaries_by_window.last_by_house ?? []}
    houseId={selectedHouse}
    onSelect={selectHouse}
  />

  <details class="rigor-block" bind:open={rigorOpen}>
    <summary>
      <span class="rigor-title">Abrir os números completos</span>
      <span class="rigor-hint">gráficos por casa, erro comum, teste fora da amostra, cobertura e glossário</span>
    </summary>

    <section class="content-section" aria-labelledby="scorecard-title">
      <div class="section-heading">
        <div>
          <p class="eyebrow">Comparação entre casas</p>
          <h2 id="scorecard-title">Erro médio por casa</h2>
        </div>
        <p>Média bruta e encolhida lado a lado, com incerteza.</p>
      </div>

      <div class="lab-controls">
        <div class="period-tabs" role="group" aria-label="Janela de comparação">
          {#each WINDOWS as option}
            <button type="button" class:active={windowId === option.id} aria-pressed={windowId === option.id}
              onclick={() => { windowId = option.id; persist('push'); }}>{option.label}</button>
          {/each}
        </div>
        <div class="period-tabs" role="group" aria-label="Métrica">
          <button type="button" class:active={metric === 'mae'} aria-pressed={metric === 'mae'}
            onclick={() => { metric = 'mae'; persist(); }}>Erro absoluto (MAE)</button>
          <button type="button" class:active={metric === 'margin'} aria-pressed={metric === 'margin'}
            onclick={() => { metric = 'margin'; persist(); }}>Erro de margem</button>
        </div>
        <div class="period-tabs" role="group" aria-label="Tipo de visualização">
          <button type="button" class:active={view === 'dots'} aria-pressed={view === 'dots'}
            onclick={() => { view = 'dots'; persist(); }}>Pontos</button>
          <button type="button" class:active={view === 'bars'} aria-pressed={view === 'bars'}
            onclick={() => { view = 'bars'; persist(); }}>Barras</button>
          <button type="button" class:active={view === 'heatmap'} aria-pressed={view === 'heatmap'}
            onclick={() => { view = 'heatmap'; persist(); }}>Mapa de calor</button>
        </div>
      </div>

      {#if view === 'heatmap'}
        <HouseHeatmap {cells} {metric} />
      {:else}
        <HouseErrorChart {houses} {grandMean} kind={view} {metric} />
      {/if}

      <p class="inline-note">
        {#if metric === 'mae'}
          Menor é melhor. A média encolhida puxa casas com poucas eleições para a média geral;
          {pooledK === null
            ? ' o encolhimento é total porque a variância entre casas não é distinguível do ruído.'
            : ` o peso na própria casa é n/(n+${formatNumber(pooledK)}).`}
        {:else}
          Positivo significa que a casa mostrou a disputa mais folgada do que a urna confirmou.
          Este número ainda inclui o erro comum da eleição — veja a tabela de erro comum abaixo.
        {/if}
      </p>
    </section>

    <section class="content-section" aria-labelledby="house-detail-title">
      <div class="section-heading">
        <div>
          <p class="eyebrow">Ficha por instituto</p>
          <h2 id="house-detail-title">Detalhe por eleição e turno</h2>
        </div>
        <p>Selecione uma casa para ver 2010, 2014, 2018 e 2022 separados por turno.</p>
      </div>
      <label class="house-select">
        <span>Casa</span>
        <select bind:value={selectedHouse} onchange={() => persist('push')}>
          <option value="">Escolha um instituto…</option>
          {#each houses as house}
            <option value={house.house_id}>{house.house_name} ({house.n_cells} célula{house.n_cells === 1 ? '' : 's'})</option>
          {/each}
        </select>
      </label>

      {#if detail}
        <div class="house-detail-head">
          <h3>{detail.house_name}</h3>
          <dl>
            <div><dt>MAE bruto</dt><dd>{detail.mae_raw === null ? '—' : `${formatNumber(detail.mae_raw)} p.p.`}</dd></div>
            <div><dt>MAE encolhido</dt><dd>{detail.mae_shrunk === null ? '—' : `${formatNumber(detail.mae_shrunk)} p.p.`}</dd></div>
            <div><dt>Erro de margem</dt><dd>{detail.margin_error_raw === null ? '—' : `${formatNumber(detail.margin_error_raw)} p.p.`}</dd></div>
            <div><dt>Acerto de liderança</dt><dd>{formatNumber(detail.leader_correct_rate * 100)}%</dd></div>
            <div><dt>Pesquisas</dt><dd>{detail.n_observations} em {detail.n_cells} célula(s)</dd></div>
            <div><dt>Identidade</dt><dd>{detail.identity_bases.join(', ')}</dd></div>
          </dl>
          {#if detail.status !== 'scored'}
            <p class="inline-note warn">Uma única célula eleição/turno: o número bruto desta casa não é comparável aos demais sem encolhimento.</p>
          {/if}
        </div>
        <DataTable label={`Desempenho de ${detail.house_name} por eleição e turno`}>
          <table>
            <thead><tr><th>Eleição</th><th>Turno</th><th class="num">Pesquisas</th><th class="num">MAE</th><th class="num">Erro margem</th><th class="num">Erro comum</th><th class="num">Relativo à eleição</th><th>Camada</th></tr></thead>
            <tbody>
              {#each detailCells as cell}
                <tr>
                  <th scope="row">{cell.year}</th>
                  <td>T{cell.turn}</td>
                  <td class="num">{cell.n}</td>
                  <td class="num">{cell.mae.mean === null ? '—' : formatNumber(cell.mae.mean)}</td>
                  <td class="num">{cell.margin_error.mean === null ? '—' : formatNumber(cell.margin_error.mean)}</td>
                  <td class="num">{cell.common_margin_error === null ? '—' : formatNumber(cell.common_margin_error)}</td>
                  <td class="num">{cell.relative_margin_error === null ? '—' : formatNumber(cell.relative_margin_error)}</td>
                  <td>{cell.evidence_tier}</td>
                </tr>
              {/each}
            </tbody>
          </table>
        </DataTable>
      {:else}
        <p class="inline-note">Nenhum instituto selecionado.</p>
      {/if}
    </section>

    <section class="content-section" aria-labelledby="common-title">
      <div class="section-heading">
        <div>
          <p class="eyebrow">Erro comum × erro da casa</p>
          <h2 id="common-title">Quando todo mundo erra junto</h2>
        </div>
        <p>A parte compartilhada não é evidência sobre nenhuma casa.</p>
      </div>
      <DataTable label="Erro comum por eleição e turno">
        <table>
          <thead><tr><th>Eleição</th><th>Turno</th><th class="num">Casas</th><th class="num">Erro de margem comum</th><th class="num">Dispersão entre casas</th><th class="num">MAE comum</th></tr></thead>
          <tbody>
            {#each effects as effect}
              <tr>
                <th scope="row">{effect.year}</th>
                <td>T{effect.turn}</td>
                <td class="num">{effect.houses}</td>
                <td class="num">{formatNumber(effect.common_margin_error)}</td>
                <td class="num">{effect.common_margin_error_sd_between_houses === null ? '—' : formatNumber(effect.common_margin_error_sd_between_houses)}</td>
                <td class="num">{formatNumber(effect.common_mae)}</td>
              </tr>
            {/each}
          </tbody>
        </table>
      </DataTable>
      <p class="inline-note" id="erro-comum">
        Cada casa vale um voto neste cálculo, para que um instituto prolífico não defina sozinho
        o que conta como “erro comum”.
      </p>
    </section>

    <section class="content-section" aria-labelledby="persistence-title">
      <div class="section-heading">
        <div>
          <p class="eyebrow">Teste fora da amostra</p>
          <h2 id="persistence-title">O viés de uma casa se repete?</h2>
        </div>
        <p id="persistencia">Se não se repete, não vira correção.</p>
      </div>
      <div class="persistence-grid">
        {#each Object.entries(history.lab.persistence) as [key, result]}
          <article class:rejected={!result.correction_authorized}>
            <header><strong>{key}</strong><span>{result.correction_authorized ? 'autoriza correção' : 'não autoriza'}</span></header>
            {#if result.model_mae_pp !== undefined && result.null_mae_pp !== undefined}
              <p>
                Prever pelo passado da casa: <strong>{formatNumber(result.model_mae_pp)} p.p.</strong> de erro.
                Prever zero: <strong>{formatNumber(result.null_mae_pp)} p.p.</strong>
              </p>
              <p class="small">
                Acordo de sinal {result.sign_agreement_rate === null || result.sign_agreement_rate === undefined ? '—' : `${formatNumber(result.sign_agreement_rate * 100)}%`}
                · {result.n_folds} folds · desenho {result.design ?? '—'}
              </p>
            {/if}
            <p class="small">{result.reason}</p>
          </article>
        {/each}
      </div>
      <p class="inline-note">{persistence.decision_rule}</p>
      <p class="inline-note">
        <strong>Eixo ideológico:</strong> {ideology.verdict_plain}
        <a href="/cenario-corrigido#eixo-ideologico" data-route>Ver o teste completo e o cenário corrigido.</a>
      </p>
    </section>

    <section class="content-section" aria-labelledby="coverage-title">
      <div class="section-heading">
        <div>
          <p class="eyebrow">Cobertura e lacunas</p>
          <h2 id="coverage-title">O que existe e o que falta</h2>
        </div>
        <p id="cobertura">Ausência declarada, nunca preenchida por suposição.</p>
      </div>
      <DataTable label="Cobertura por ano e turno">
        <table>
          <thead><tr><th>Ano</th><th>Turno</th><th class="num">Registros</th><th class="num">Pontuadas</th><th class="num">Casas</th><th class="num">Elegíveis ao motor</th><th>Camada</th><th>Situação</th></tr></thead>
          <tbody>
            {#each coverage.cells as cell}
              <tr class:absent={cell.status === 'absent'}>
                <th scope="row">{cell.year}</th>
                <td>T{cell.turn}</td>
                <td class="num">{cell.records}</td>
                <td class="num">{cell.scored_observations}</td>
                <td class="num">{cell.n_houses}</td>
                <td class="num">{cell.engine_eligible_polls}</td>
                <td>{cell.corpus_tier ?? '—'}</td>
                <td>{cell.status === 'covered' ? 'coberta' : cell.status === 'thin' ? 'fina' : 'ausente'}</td>
              </tr>
            {/each}
          </tbody>
        </table>
      </DataTable>
      <ul class="gap-list">
        {#each coverage.known_gaps as gap}
          <li class:blocking={gap.blocking}><strong>{gap.gap}</strong><span>{gap.detail}</span></li>
        {/each}
      </ul>
    </section>

    <section class="content-section" aria-labelledby="glossary-title">
      <div class="section-heading">
        <div>
          <p class="eyebrow">Glossário</p>
          <h2 id="glossary-title">O que cada número significa</h2>
        </div>
      </div>
      <dl class="metric-glossary">
        {#each definitions as definition}
          <div>
            <dt>{definition.label}</dt>
            <dd>
              <p>{definition.plain}</p>
              <code>{definition.formula}</code>
            </dd>
          </div>
        {/each}
      </dl>
    </section>
  </details>
</section>
